\title{Nonstabilizerness of quantum tensor network states is intractable in two dimensions}

\author{Gianluca Esposito}
\affiliation{Scuola Superiore Meridionale, Largo S. Marcellino 10, 80138 Naples, Italy}
\affiliation{Istituto Nazionale di Fisica Nucleare, Sezione di Napoli}
